solution.solution.cpp:
#include <cstddef>
#include <memory>
#include <utility>

template <typename T>
class Slot
{
public:
    Slot() = default;
    Slot(const Slot&) = delete;
    Slot& operator=(const Slot&) = delete;
    ~Slot() { reset(); }

    template <typename... Args>
    T& emplace(Args&&... args)
    {
        reset();
        T* object{ std::construct_at(pointer(), std::forward<Args>(args)...) };
        m_alive = true;
        return *object;
    }

    void reset()
    {
        if (m_alive)
        {
            std::destroy_at(pointer());
            m_alive = false;
        }
    }

    bool hasValue() const { return m_alive; }
    T& get() { return *pointer(); }

private:
    T* pointer() { return reinterpret_cast<T*>(m_storage); }

    alignas(T) std::byte m_storage[sizeof(T)];
    bool m_alive{ false };
};

unitTests:
struct Probe { static inline int alive{ 0 }; int id; explicit Probe(int i) : id{ i } { ++alive; } ~Probe() { --alive; } };

TEST("empty until something is emplaced") { Slot<Probe> s{}; CHECK(!s.hasValue()); CHECK_EQ(Probe::alive, 0); }
TEST("emplace constructs in place") { Slot<Probe> s{}; Probe& p{ s.emplace(7) }; CHECK(s.hasValue()); CHECK_EQ(p.id, 7); CHECK_EQ(s.get().id, 7); CHECK_EQ(Probe::alive, 1); CHECK(static_cast<void*>(&p) == static_cast<void*>(&s)); }
TEST("emplacing again destroys the old object first") { Slot<Probe> s{}; s.emplace(1); s.emplace(2); CHECK_EQ(Probe::alive, 1); CHECK_EQ(s.get().id, 2); }
TEST("reset and the destructor both clean up") { { Slot<Probe> s{}; s.emplace(3); s.reset(); CHECK_EQ(Probe::alive, 0); CHECK(!s.hasValue()); s.emplace(4); } CHECK_EQ(Probe::alive, 0); }
TEST("it uses no heap memory, and works for bigger types") { CHECK_NO_LEAK(Slot<std::array<double, 64>> s{}; s.emplace(); s.get()[63] = 1.5); static_assert(sizeof(Slot<double>) <= 2 * sizeof(double)); static_assert(alignof(Slot<double>) == alignof(double)); Slot<std::string> text{}; CHECK_EQ(text.emplace(5, 'x'), "xxxxx"); }

